#include <ctype.h>
#include <stdio.h>
#include <string.h>

#define GROUP 4096

static char groups[4][GROUP];

static void add(int group, const char *name) {
    strcat(groups[group], " ");
    strcat(groups[group], name);
}

int main(void) {
    static const char *titles[] = {"функции", "данные", "нужны извне", "локальные"};
    char line[256];
    char a[64];
    char b[64];
    char c[64];
    while (fgets(line, sizeof line, stdin) != NULL) {
        int words = sscanf(line, "%63s %63s %63s", a, b, c);
        const char *letter;
        const char *name;
        if (words == 3) {
            letter = b;
            name = c;
        } else if (words == 2) {
            letter = a;
            name = b;
        } else {
            continue;
        }
        char kind = letter[0];
        if (islower((unsigned char)kind)) {
            add(3, name);
        } else if (kind == 'T') {
            add(0, name);
        } else if (kind == 'D' || kind == 'B' || kind == 'R') {
            add(1, name);
        } else if (kind == 'U') {
            add(2, name);
        }
    }
    for (int i = 0; i < 4; i++) {
        printf("%s:%s\n", titles[i], groups[i][0] != '\0' ? groups[i] : " -");
    }
    return 0;
}

